// Generic LLM Gateway contract (FR3): every path returns either
// { success: true, data: <parsed structured object> } or
// { success: false, error: <short message>, statusCode: <number|null> } -- never
// an unhandled throw. statusCode is new (fallback-router support): it lets a
// downstream IF node distinguish a genuine quota exhaustion (429 /
// RESOURCE_EXHAUSTED, confirmed live at 20 requests/day for gemini-3.6-flash --
// see .specclaw/learnings.md L27) from any other failure, without needing to
// re-inspect Gemini's raw response body a second time.
try {
  const response = $json || {};

  // A network-level failure (DNS, timeout, connection refused) surfaces here
  // as an n8n error object rather than a normal HTTP response, since the
  // HTTP Request node uses onError=continueRegularOutput. The axios error's
  // own `status` field (when present) still carries the real HTTP status
  // even though `neverError` is false and the full response body was
  // discarded -- confirmed live during the L27 investigation.
  if (response.error) {
    const message =
      (typeof response.error === 'string' && response.error) ||
      (response.error && response.error.message) ||
      'Request to Gemini failed';
    const statusCode =
      response.error && typeof response.error.status === 'number' ? response.error.status : null;
    return { json: { success: false, error: String(message), statusCode } };
  }

  const statusCode = response.statusCode;
  const body = response.body;

  if (!statusCode || statusCode < 200 || statusCode >= 300) {
    const apiMessage =
      body && body.error && body.error.message
        ? body.error.message
        : `Gemini API returned HTTP ${statusCode}`;
    return { json: { success: false, error: String(apiMessage), statusCode: statusCode || null } };
  }

  const candidates = (body && body.candidates) || [];
  const parts =
    (candidates[0] && candidates[0].content && candidates[0].content.parts) || [];
  const text = parts[0] && parts[0].text;

  if (!text) {
    return {
      json: { success: false, error: 'Gemini response contained no text to parse', statusCode },
    };
  }

  let data;
  try {
    data = JSON.parse(text);
  } catch (parseErr) {
    return { json: { success: false, error: 'Gemini response was not valid JSON', statusCode } };
  }

  return { json: { success: true, data } };
} catch (err) {
  return { json: { success: false, error: (err && err.message) || 'Unknown LLM Gateway error', statusCode: null } };
}

// Same generic contract as 'Parse Gemini response': { success: true, data }
// or { success: false, error }. This is the last tier -- no further fallback
// beyond OpenRouter, so any failure here is a genuine final failure.
try {
  const response = $json || {};

  if (response.error) {
    const message =
      (typeof response.error === 'string' && response.error) ||
      (response.error && response.error.message) ||
      'Request to OpenRouter failed';
    return { json: { success: false, error: String(message) } };
  }

  const statusCode = response.statusCode;
  const body = response.body;

  if (!statusCode || statusCode < 200 || statusCode >= 300) {
    const apiMessage =
      body && body.error && body.error.message
        ? body.error.message
        : `OpenRouter API returned HTTP ${statusCode}`;
    return { json: { success: false, error: String(apiMessage) } };
  }

  const choices = (body && body.choices) || [];
  const content = choices[0] && choices[0].message && choices[0].message.content;

  if (!content) {
    return { json: { success: false, error: 'OpenRouter response contained no content to parse' } };
  }

  let data;
  try {
    data = JSON.parse(content);
  } catch (parseErr) {
    return { json: { success: false, error: 'OpenRouter response was not valid JSON' } };
  }

  return { json: { success: true, data } };
} catch (err) {
  return { json: { success: false, error: (err && err.message) || 'Unknown OpenRouter fallback error' } };
}
